import assert from 'node:assert/strict';
import {readFileSync,readdirSync,lstatSync,readlinkSync,existsSync} from 'node:fs';
import {join} from 'node:path';
import {spawnSync} from 'node:child_process';
import {createConnection} from 'node:net';
import {inventory,sourceFingerprint,sha256,repository} from './scripts/documentation-lib.mjs';
import {privateRedactionValues} from './scripts/evidence-lib.mjs';
assert.equal(sourceFingerprint(),'831cb35f241bab4ac7ff320dc3eafa1fc553e8a1fe93e88b49e43d49412ffb6e');
const credentials=Object.values(privateRedactionValues(repository));assert.equal(credentials.length,9);
const publicPaths=inventory();
for(const path of publicPaths){const bytes=readFileSync(path);for(const value of credentials)assert.equal(bytes.includes(Buffer.from(value)),false,'private value found in public path: '+path);}
for(const path of ['.env.local','.local/database.json']){
 const s=lstatSync(path);assert.equal(s.mode&0o777,0o600);assert.equal(s.uid,process.getuid());assert.equal(s.isSymbolicLink(),false);assert.equal(s.nlink,1);
 assert.equal(spawnSync('git',['check-ignore','-q',path]).status,0);
 const intake=JSON.parse(readFileSync('docs/validation/runs/RUN-20261011-014.json'));
 assert.ok(s.mtimeMs<=Date.parse(intake.started_at),'private file modified after intake');
}
assert.equal(lstatSync('.local').mode&0o777,0o700);
console.log('PASS known private values absent from all public source/receipts/logs; private files owned0600/ignored with mtimes preceding intake.');
let runs=0;
for(const name of readdirSync('docs/validation/runs').filter(n=>/^RUN-20261011-\d{3}\.json$/.test(n)&&Number(n.slice(-8,-5))>=14)){
 const r=JSON.parse(readFileSync(join('docs/validation/runs',name)));assert.equal(sha256(readFileSync(r.log_path)),r.log_sha256);runs++;
}
assert.equal(runs,48);console.log('PASS48 retained RULE-02 execution logs match their original receipt digests, including failures.');
const args=process.env.PY_REQUIREMENT_CHECK;assert.ok(args);
const csv=spawnSync('python3',['-c',args],{stdio:'inherit'});assert.equal(csv.status,0);
for(const path of ['SHA256SUMS.txt','VALIDATION_RESULTS.json','docs/vision/Development_Blueprint_2026-10-05.md','docs/vision/original_action_items.md','docs/vision/dependencies.json','docs/vision/source_register.json','docs/vision/additional_scope.csv','docs/vision/decision_register.csv','docs/vision/rules_certification_template.csv']){
 const base=spawnSync('git',['show','HEAD:'+path]);assert.equal(base.status,0);assert.ok(readFileSync(path).equals(base.stdout),'immutable baseline changed: '+path);
}
console.log('PASS original vision/decision/source/dependency/certification/archive provenance bytes preserved.');
for(const port of [5173,3001,3002]){
 await new Promise((resolve,reject)=>{const s=createConnection({host:'127.0.0.1',port});s.setTimeout(1500);s.once('connect',()=>{s.destroy();reject(new Error('Unexpected listener on '+port));});s.once('timeout',()=>{s.destroy();reject(new Error('Inconclusive listener probe'));});s.once('error',e=>e.code==='ECONNREFUSED'?resolve():reject(e));});
}
let scanned=0;
for(const pid of readdirSync('/proc').filter(p=>/^\d+$/.test(p)&&Number(p)!==process.pid)){
 try {
  const args=readFileSync('/proc/'+pid+'/cmdline','utf8').split('\0').filter(Boolean);const cwd=readlinkSync('/proc/'+pid+'/cwd');
  if(!/^(?:node|bun)$/.test(args[0]?.split('/').at(-1)??''))continue;
  scanned++;
  assert.ok(!args.some(a=>a==='scripts/dev.mjs'||a.endsWith('/scripts/dev.mjs')||/apps\/(?:api|match-service|worker)\/(?:src|dist)\/main\.(?:ts|js)$/.test(a)),'Owned service process remains');
  assert.ok(!(cwd.startsWith(repository+'apps/')&&args.some(a=>a==='src/main.ts'||a==='dist/main.js')),'Owned service process remains');
  assert.ok(!args.some(a=>/node_modules\/.*(?:vite\/bin\/vite|playwright.*(?:cli|run-server))/.test(a)),'Owned browser/dev process remains');
 } catch(e){if(!['ENOENT','EACCES'].includes(e.code))throw e;}
}
console.log('PASS actual container ports5173/3001/3002 refused; no owned dev/service/browser executables among '+scanned+' inspected Node/Bun processes.');
assert.ok(readFileSync('.local/rule-02/canonical-check.mjs').equals(readFileSync('docs/validation/rule-02-canonical-check.mjs.txt')));
const host=JSON.parse(readFileSync('docs/validation/rule-02-host-closure.json'));
assert.equal(host.category,'host_inspection');assert.equal(host.result,'passed');assert.equal(host.source_fingerprint,sourceFingerprint());
assert.equal(Object.values(host.remaining).flat().length,0);assert.equal(host.isolated_image_absent,true);
console.log('PASS retained canonical program identity and separately attributed WSL host cleanup report at '+host.observed_at);
